using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Windows.Forms;
namespace Ara {
 public static class HistoryTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static State New(){var s=State.New();var d=s.GetDay(DateTime.Today);d.Wake=DateTime.Today.AddHours(8);GridEngine.Ensure(s,d);return s;}
  static void With(string dir,string name,Action<MainForm> action){using(var f=new MainForm(new Store(Path.Combine(dir,"history-"+name+".json")),New(),true)){f.Show();Application.DoEvents();try{action(f);}finally{f.Quit();}}}
  static PhoneCommand Command(MainForm f,string op,int first,int last,int lane=1){return new PhoneCommand{op=op,first=first,last=last,lane=lane,date=f.Day.Date,baseRevision=f.PhoneSnapshot(f.Day.Date).revision,requestId=Guid.NewGuid().ToString("N")};}
  static PhoneBlock Meal(PhoneDay v,string id){return v.planned.Single(x=>x.mealId==id);}
  static PhoneDay Eat(MainForm f,string id,int start){var source=Meal(f.PhoneSnapshot(f.Day.Date),id);var c=Command(f,"copy",start,start+2);c.sourceId=source.id;return f.PhoneApply(c);}
  static PhoneDay MoveActual(MainForm f,string meal,int start){var actual=f.PhoneSnapshot(f.Day.Date).actual.Single(x=>x.mealId==meal);var c=Command(f,"move",start,start);c.id=actual.id;return f.PhoneApply(c);}
  static void Same(PhoneBlock a,PhoneBlock b){Assert(a.id==b.id&&a.start==b.start&&a.count==b.count&&a.category==b.category&&a.name==b.name,"planned block changed");}
  public static void Run(Action<string,Action> check,string dir){
   check("history: midnight restart keeps the ongoing wake day until its sleep target",()=>{var s=New();var d=s.Days[0];d.Wake=DateTime.Today.AddHours(15);Assert(MainForm.DefaultDate(s,d.Wake.Date.AddDays(1).AddHours(2))==d.Wake.Date,"ongoing overnight day");Assert(MainForm.DefaultDate(s,d.Wake.Date.AddDays(1).AddHours(8))==d.Wake.Date.AddDays(1),"new day after sleep target");});
   check("history: late second meal leaves its planned time and all earlier plans untouched",()=>With(dir,"late-two",f=>{var before=f.PhoneSnapshot(f.Day.Date);var second=Meal(before,"b6");var after=Eat(f,"b6",second.start+6);Same(second,Meal(after,"b6"));foreach(var b in before.planned.Where(x=>x.start<=second.start))Same(b,after.planned.Single(x=>x.id==b.id));Assert(after.actual.Single().start==second.start+6,"actual separate");Assert(after.planned.Single(x=>x.category=="웨이트").start!=before.planned.Single(x=>x.category=="웨이트").start,"future changed");Assert(f.Board.Planned.Single(x=>x.MealId=="b6").Start==f.Day.Wake.Date.AddMinutes(second.start*10),"PC shows fixed plan");f.ToggleDarkMode();f.Board.Jump(f.Day.Wake.Date.AddHours(10));using(var picture=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(picture,new Rectangle(Point.Empty,f.Size));picture.Save(Path.Combine(dir,"fixed-plan-dark-pc.png"));}}));
   check("history: early second meal advances future third meal without rewriting current plan",()=>With(dir,"early-two",f=>{var before=f.PhoneSnapshot(f.Day.Date);var second=Meal(before,"b6");var after=Eat(f,"b6",second.start-2);Same(second,Meal(after,"b6"));Assert(Meal(after,"b10").start==second.start-2+18,"three hours from actual eating start");Assert(after.actual.Single().start==second.start-2,"actual visible separately");}));
   check("history: current meal freezes its latest adjusted plan rather than the original default",()=>With(dir,"adjusted",f=>{var initial=f.PhoneSnapshot(f.Day.Date);Eat(f,"b1",Meal(initial,"b1").start+9);var adjusted=f.PhoneSnapshot(f.Day.Date);var second=Meal(adjusted,"b6");Assert(second.start!=Meal(initial,"b6").start,"future second was adjusted");var after=Eat(f,"b6",second.start+1);Same(second,Meal(after,"b6"));foreach(var b in adjusted.planned.Where(x=>x.start<=second.start))Same(b,after.planned.Single(x=>x.id==b.id));Same(Meal(initial,"b1"),Meal(after,"b1"));}));
   check("history: editing actual second meal repeatedly never moves its fixed upper plan",()=>With(dir,"edit",f=>{var initial=f.PhoneSnapshot(f.Day.Date);Eat(f,"b1",Meal(initial,"b1").start+9);var second=Meal(f.PhoneSnapshot(f.Day.Date),"b6");Eat(f,"b6",second.start+1);for(int step=2;step<=6;step++){var after=MoveActual(f,"b6",second.start+step);Same(second,Meal(after,"b6"));Assert(after.actual.Single(x=>x.mealId=="b6").start==second.start+step,"actual moved");}}));
   check("history: manual future edits do not reapply past meal delays",()=>With(dir,"manual-future",f=>{var initial=f.PhoneSnapshot(f.Day.Date);Eat(f,"b1",Meal(initial,"b1").start+9);var second=Meal(f.PhoneSnapshot(f.Day.Date),"b6");Eat(f,"b6",second.start+1);var before=f.PhoneSnapshot(f.Day.Date);var c=Command(f,"category",84,86,0);c.category="작업";var after=f.PhoneApply(c);foreach(var b in before.planned)Same(b,after.planned.Single(x=>x.id==b.id));Assert(after.planned.Any(x=>x.category=="작업"&&x.start==84),"new future work");var next=MoveActual(f,"b1",before.actual.Single(x=>x.mealId=="b1").start-3);Same(second,Meal(next,"b6"));Assert(next.planned.Single(x=>x.category=="웨이트").start==after.planned.Single(x=>x.category=="웨이트").start,"fixed second actual keeps following times stable");}));
   check("history: deleting current upper meal keeps actual anchor and future schedule",()=>With(dir,"delete-upper",f=>{var initial=f.PhoneSnapshot(f.Day.Date);var second=Meal(initial,"b6");var before=Eat(f,"b6",second.start-2);var c=Command(f,"delete",second.start,second.start,0);var after=f.PhoneApply(c);Assert(!after.planned.Any(x=>x.mealId=="b6")&&after.actual.Single().mealId=="b6","only upper block deleted");Same(Meal(before,"b10"),Meal(after,"b10"));var moved=MoveActual(f,"b6",second.start-1);Assert(Meal(moved,"b10").start>=moved.actual.Single().start+18,"missing upper meal still anchors physiology");}));
   check("history: deleted delay releases frozen plans and restores baseline when no records remain",()=>With(dir,"delete-actual",f=>{var initial=f.PhoneSnapshot(f.Day.Date);var second=Meal(initial,"b6");Eat(f,"b6",second.start+6);var actual=f.PhoneSnapshot(f.Day.Date).actual.Single();var after=f.PhoneApply(Command(f,"delete",actual.start,actual.start));Assert(after.actual.Count==0&&f.Day.PlanHistoryIds.Count==0&&f.Day.PlanHistory.Count==0,"locks released");foreach(var b in initial.planned)Same(b,after.planned.Single(x=>x.id==b.id));}));
   check("history: JSON restart retains fixed current plans and actual times",()=>With(dir,"restart",f=>{var initial=f.PhoneSnapshot(f.Day.Date);Eat(f,"b1",Meal(initial,"b1").start+9);var second=Meal(f.PhoneSnapshot(f.Day.Date),"b6");Eat(f,"b6",second.start+1);var before=f.PhoneSnapshot(f.Day.Date);var loaded=f.Store.Load();var after=PhoneCodec.Snapshot(loaded,f.Day.Date);Assert(after.revision==before.revision&&loaded.GetDay(f.Day.Wake.Date).PlanHistory.Count>0,"durable fixed plan");Same(second,Meal(after,"b6"));}));
   check("history: undo restores both the frozen plan and actual record state",()=>With(dir,"undo",f=>{var initial=f.PhoneSnapshot(f.Day.Date);var second=Meal(initial,"b6");Eat(f,"b6",second.start+3);var id=f.Data.RemoteReceipts.Last().id;var undo=Command(f,"undo",0,0);undo.sourceId=id;var after=f.PhoneApply(undo);Assert(after.actual.Count==0&&f.Day.PlanHistoryIds.Count==0,"history and actual undo");Same(second,Meal(after,"b6"));}));
   check("history: planned workout length stays fixed after recording a shorter workout",()=>With(dir,"weight",f=>{var before=f.PhoneSnapshot(f.Day.Date);var weight=before.planned.Single(x=>x.category=="웨이트");var c=Command(f,"copy",weight.start,weight.start+5);c.sourceId=weight.id;var after=f.PhoneApply(c);Same(weight,after.planned.Single(x=>x.id==weight.id));Assert(after.actual.Single().count==6,"actual hour, planned two hours");foreach(var b in before.planned.Where(x=>x.start<=weight.start))Same(b,after.planned.Single(x=>x.id==b.id));}));
   check("history: frozen workout plan never creates another reminder after it was recorded",()=>With(dir,"weight-reminder",f=>{var before=f.PhoneSnapshot(f.Day.Date);var weight=before.planned.Single(x=>x.category=="웨이트");var c=Command(f,"copy",weight.start-6,weight.start-1);c.sourceId=weight.id;f.PhoneApply(c);var plan=GridEngine.AsPlan(f.Data,f.Day,f.GridPlan);var slot=plan.Slots.Single(x=>x.Block.Id==weight.id);Assert(slot.Done&&slot.Actual,"performed weight marked done");Assert(!Reminders.Due(f.Data,f.Day,plan,slot.Start.AddMinutes(-f.Data.ReminderMinutes)).Any(x=>x.Block.Id==weight.id),"no duplicate workout reminder");}));
  }
 }
}
